export const unlockedCountries=round=>regions.filter(r=>r.round<=round);
export const flagUrl=id=>worldId==='kyrgyzstan'?new URL('../assets/coastal/kyrgyzstan/flag.svg',import.meta.url).href:new URL('../assets/coastal/flags/'+id+'.svg',import.meta.url).href;
export function countryQuestions(id){const r=regions.find(r=>r.id===id),d=countryLearning[id];return [
 {prompt:(worldId==='kyrgyzstan'?'What is the regional centre of ':'What is the capital of ')+r.name+'?',options:[r.capital,...regions.filter(x=>x.id!==id).slice(0,2).map(x=>x.capital)],explanation:r.facts[0]},
 {prompt:d.question[0],options:d.question.slice(1),explanation:[...r.facts,...d.extra,'Waterways: '+d.water].join(' ')},
 {prompt:'Which landmark would you visit in '+r.name+'?',options:[d.landmarks[0][0],...Object.entries(countryLearning).filter(([key])=>key!==id).slice(0,2).map(([,v])=>v.landmarks[0][0])],explanation:d.landmarks[0][0]+' is in '+d.landmarks[0][1]+'. '+d.landmarks[0][2]}
 ];}
export const quizQuestions=city=>[...cityQuestions(city),...countryQuestions(geoStops[city].region)];
export const questionForCoin=coin=>Number.isInteger(coin.city)?quizQuestions(coin.city)[coin.question]:countryQuestions(coin.region)[coin.question];
export const freshLearning=()=>({clock:0,serial:0,coin:null,earned:0,bags:{},last:{}});
export function advanceLearning(state,dt){
 state.learning??=freshLearning();const l=state.learning;if(l.coin)return;l.clock+=dt;if(l.clock<(l.serial===0?12:30))return;l.clock=0;l.serial++;
 const known=geoStops.filter(s=>s.round<=state.round),latest=Math.max(...known.map(s=>s.round)),current=known.filter(s=>s.round===latest),city=current[(l.serial-1)%current.length];
 l.bags??={};l.last??={};l.rng??=(state.rng>>>0)||12345;
 const random=()=>{l.rng=(Math.imul(l.rng,1664525)+1013904223)>>>0;return l.rng/4294967296;};
 if(!l.bags[city.id]?.length){const bag=quizQuestions(city.id).map((_,i)=>i);for(let i=bag.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]];}if(bag.at(-1)===l.last[city.id])[bag[0],bag[bag.length-1]]=[bag.at(-1),bag[0]];l.bags[city.id]=bag;}
 const question=l.bags[city.id].pop();l.last[city.id]=question;l.coin={id:l.serial,city:city.id,region:city.region,question,x:24+(l.serial*23)%53,y:26+(l.serial*13)%38};
}
import {recordKnowledge} from './coastal-expedition.js';
export function answerGeographyCoin(state,coinId,choice){const l=state.learning,coin=l?.coin;if(!coin||coin.id!==coinId)return null;const q=questionForCoin(coin);if(!q||!q.options.includes(choice))return null;const correct=choice===q.options[0],reward=correct?15:0;state.credits+=reward;if(correct)recordKnowledge(state,coin.region);l.earned+=reward;l.coin=null;return {correct,reward,answer:q.options[0],explanation:q.explanation};}
